def fm(doc,agent,domain="coaching"):
 return {"id":doc["id"],"title":doc["title"],"document_type":"playbook","domain":domain,"agents":[agent] if agent in {"alfred","feedbacker"} else ["alfred","feedbacker"],"trigger_phrases":doc["terms"],"use_when":doc["terms"],"source_ids":[],"language":"pt-BR","version":"2.0.0","status":"machine_audited","requires_human_review":True,"index_eligible":False,"risk_level":"high" if doc["id"]=="pb-a-safety-handoff" else "low","last_machine_audited_at":TODAY}

def render_a(d):
 meta=fm(d,"alfred"); meta["related_knowledge"]=d["knowledge"]; meta["candidate_techniques"]=d["techniques"]
 tree="\n".join(f"- {x}" for x in d["tree"])
 return "---\n"+yaml.safe_dump(meta,allow_unicode=True,sort_keys=False).strip()+"\n---\n\n"+f"# {d['title']}\n\n## Critérios de ativação\n\n{d['activate']}\n\n## Situações semelhantes que não devem ativá-lo\n\n{d['exclude']}\n\n## O que pode estar acontecendo\n\n{d['interpret']}\n\n## O que ainda não sabemos\n\n{d['unknown']}\n\n## Árvore de decisão\n\n{tree}\n\n## Conhecimentos relacionados\n\n{', '.join(f'`{x}`' for x in d['knowledge']) or 'Nenhum; aplicar política compartilhada.'}\n\n## Técnicas candidatas e condições\n\n{', '.join(f'`{x}`' for x in d['techniques']) or 'Nenhuma técnica de coaching deve ser aplicada neste fluxo.'}\n\n## Como responder naturalmente\n\n{d['response']}\n\n## Quando não fazer pergunta\n\n{d['no_question']}\n\n## Quando não oferecer solução\n\n{d['no_solution']}\n\n## Quando usar referência científica\n\n{d['reference']}\n\n## Quando encerrar ou mudar de fluxo\n\n{d['exit']}\n\n## Segurança\n\nAplicar a camada determinística antes do RAG sempre que houver gatilho crítico; este playbook não substitui triagem profissional.\n"

def render_f(d):
 meta=fm(d,"feedbacker","structured_analysis")
 return "---\n"+yaml.safe_dump(meta,allow_unicode=True,sort_keys=False).strip()+"\n---\n\n"+f"# {d['title']}\n\n## Observação\n\n{d['observe']}\n\n## Padrão\n\n{d['pattern']}\n\n## Hipótese e confiança\n\n{d['hyp']}\n\n## Evidência favorável\n\n{d['favour']}\n\n## Evidência contrária\n\n{d['against']}\n\n## Dados ausentes\n\n{d['missing']}\n\n## Recomendação\n\n{d['recommend']}\n\n## Forma de testar\n\n{d['test']}\n\n## Critério de revisão\n\n{d['review']}\n\n## Limite\n\nConfiança qualitativa não prova causalidade e não autoriza diagnóstico.\n"

def render_s(d):
 meta=fm(d,"shared","communication")
 return "---\n"+yaml.safe_dump(meta,allow_unicode=True,sort_keys=False).strip()+"\n---\n\n"+f"# {d['title']}\n\n{d['body']}\n"

def main():
 if AUDIT.exists() or QUAR.exists(): raise SystemExit("Fase 7 já executada.")
 old=sorted(ROOT.rglob("*.md")); old_meta=[]
 for p in old: old_meta.append((p,yaml.safe_load(p.read_text(encoding="utf-8").split("---",2)[1])))
 QUAR.parent.mkdir(parents=True,exist_ok=True); shutil.move(str(ROOT),str(QUAR)); ROOT.mkdir()
 new=[]
 for folder,docs,renderer in (("alfred",ALFRED,render_a),("feedbacker",FEEDBACK,render_f),("shared",SHARED,render_s)):
  (ROOT/folder).mkdir()
  for d in docs:
   p=ROOT/folder/f"{d['id']}.md"; p.write_text(renderer(d),encoding="utf-8"); new.append((p,d,folder))
 new_ids={d["id"] for _,d,_ in new}; audit=[]; qrows=[]
 for p,m in old_meta:
  rel=p.relative_to(ROOT).as_posix(); dec="replaced_by_v2" if m["id"] in new_ids else "quarantined_redundant_or_script_like"
  row={"document_id":m["id"],"original_path":f"playbooks/{rel}","quarantine_path":f"quarantine/phase7_legacy_playbooks/{rel}","decision":dec,"phase":7,"active":False,"index_eligible":False,"requires_human_review":True}; audit.append(row); qrows.append(row)
 registry=[json.loads(x) for x in (RAG/"document_registry.jsonl").read_text(encoding="utf-8").splitlines() if x and json.loads(x).get("document_type")!="playbook"]
 for p,d,folder in new:
  meta=yaml.safe_load(p.read_text(encoding="utf-8").split("---",2)[1]); registry.append({"document_id":d["id"],"path":p.relative_to(RAG).as_posix(),"document_type":"playbook","domain":meta["domain"],"agents":meta["agents"],"situations":d["terms"],"risk_level":meta["risk_level"],"language":"pt-BR","status":"machine_audited","requires_human_review":True,"index_eligible":False,"source_ids":[],"version":"2.0.0","last_machine_audited_at":TODAY}); audit.append({"document_id":d["id"],"path":p.relative_to(RAG).as_posix(),"decision":"active_reconstructed_v2","phase":7,"status":"machine_audited","requires_human_review":True})
 registry.sort(key=lambda x:x["document_id"]); (RAG/"document_registry.jsonl").write_text("".join(json.dumps(x,ensure_ascii=False)+"\n" for x in registry),encoding="utf-8")
 existing=[json.loads(x) for x in QREG.read_text(encoding="utf-8").splitlines() if x]; QREG.write_text("".join(json.dumps(x,ensure_ascii=False)+"\n" for x in existing+qrows),encoding="utf-8"); AUDIT.write_text("".join(json.dumps(x,ensure_ascii=False)+"\n" for x in audit),encoding="utf-8")
 scores=[json.loads(x) for x in SCORES.read_text(encoding="utf-8").splitlines() if x]; scores += [{"document_id":d["id"],"document_type":"playbook","specificity":4,"evidence":4,"traceability":4,"actionability":5,"naturalness":4,"retrieval_value":4,"safety":4,"metadata":5,"status":"machine_audited","requires_human_review":True,"scored_at":TODAY} for _,d,_ in new]; SCORES.write_text("".join(json.dumps(x,ensure_ascii=False)+"\n" for x in scores),encoding="utf-8")
 print(json.dumps({"status":"ok","legacy_preserved":len(old),"active_rebuilt":len(new),"alfred":len(ALFRED),"feedbacker":len(FEEDBACK),"shared":len(SHARED)},ensure_ascii=False))

if __name__=="__main__": main()
